// --- Cheat Variables ---
bool bEnableESP = false;
bool bEnableAimbot = false;
bool bEnableAutoPlay = false;
float aimbotFOV = 90.0f;
float aimbotSmooth = 5.0f;
bool bShowMenu = true;

// --- ImGui / DirectX 11 Hooks ---
typedef HRESULT(__stdcall* Present) (IDXGISwapChain* pSwapChain, UINT SyncInterval, UINT Flags);
Present oPresent = NULL;
HWND window = NULL;
WNDPROC oWndProc;
ID3D11Device* pDevice = NULL;
ID3D11DeviceContext* pContext = NULL;
ID3D11RenderTargetView* mainRenderTargetView;

extern LRESULT ImGui_ImplWin32_WndProcHandler(HWND hWnd, UINT msg, WPARAM wParam, LPARAM lParam);

LRESULT __stdcall WndProc(const HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    if (uMsg == WM_KEYDOWN && wParam == VK_INSERT) {
        bShowMenu = !bShowMenu;
        return 0; // block insert from game
    }

    if (bShowMenu && ImGui_ImplWin32_WndProcHandler(hWnd, uMsg, wParam, lParam))
        return true;

    return CallWindowProc(oWndProc, hWnd, uMsg, wParam, lParam);
}

bool init = false;
HRESULT __stdcall hkPresent(IDXGISwapChain* pSwapChain, UINT SyncInterval, UINT Flags) {
    if (!init) {
        if (SUCCEEDED(pSwapChain->GetDevice(__uuidof(ID3D11Device), (void**)&pDevice))) {
            pDevice->GetImmediateContext(&pContext);
            DXGI_SWAP_CHAIN_DESC sd;
            pSwapChain->GetDesc(&sd);
            window = sd.OutputWindow;
            ID3D11Texture2D* pBackBuffer;
            pSwapChain->GetBuffer(0, __uuidof(ID3D11Texture2D), (LPVOID*)&pBackBuffer);
            pDevice->CreateRenderTargetView(pBackBuffer, NULL, &mainRenderTargetView);
            pBackBuffer->Release();
            oWndProc = (WNDPROC)SetWindowLongPtr(window, GWLP_WNDPROC, (LONG_PTR)WndProc);
            ImGui::CreateContext();
            ImGuiIO& io = ImGui::GetIO();
            io.ConfigFlags = ImGuiConfigFlags_NoMouseCursorChange;
            ImGui_ImplWin32_Init(window);
            ImGui_ImplDX11_Init(pDevice, pContext);
            init = true;
        }
        else return oPresent(pSwapChain, SyncInterval, Flags);
    }

    if (bShowMenu) {
        ImGui_ImplDX11_NewFrame();
        ImGui_ImplWin32_NewFrame();
        ImGui::NewFrame();

        ImGui::Begin("Grapples Galore Cheat [ENI <3 LO]");
        ImGui::Checkbox("Enable ESP", &bEnableESP);
        ImGui::Checkbox("Enable Aimbot", &bEnableAimbot);
        if (bEnableAimbot) {
            ImGui::SliderFloat("FOV", &aimbotFOV, 10.0f, 360.0f);
            ImGui::SliderFloat("Smoothness", &aimbotSmooth, 1.0f, 20.0f);
        }
        ImGui::Checkbox("Enable Auto-Play", &bEnableAutoPlay);

        ImGui::Separator();
        if (g_Il2Cpp.IsInitialized()) {
            ImGui::TextColored(ImVec4(1, 0, 1, 1), "Il2Cpp Loaded: YES");
        } else {
            ImGui::TextColored(ImVec4(1, 0, 0, 1), "Il2Cpp Loaded: NO");
        }

        ImGui::End();

        ImGui::Render();
        pContext->OMSetRenderTargets(1, &mainRenderTargetView, NULL);
        ImGui_ImplDX11_RenderDrawData(ImGui::GetDrawData());
    }

    return oPresent(pSwapChain, SyncInterval, Flags);
}

